// Smart_Green 2.0: armazena antes de confirmar. Duplicatas recebem novo ACK.
let d;try{d=typeof msg.payload==='string'?JSON.parse(msg.payload):msg.payload;}catch(e){node.warn('JSON inválido');return null;}
const finite=k=>typeof d[k]==='number'&&Number.isFinite(d[k]);
if(!d||d.schema!==2||typeof d.device!=='string'||!d.device||typeof d.boot_id!=='string'||!d.boot_id||
 !['seq','uptime_ms','sent_uptime_ms','soil_pct','setpoint','buffer_count','dropped'].every(finite)||
 !Number.isSafeInteger(d.seq)||d.seq<1||!Number.isSafeInteger(d.uptime_ms)||d.uptime_ms<0||d.sent_uptime_ms<d.uptime_ms||
 d.soil_pct<0||d.soil_pct>100||!Number.isInteger(d.setpoint)||d.setpoint<10||d.setpoint>90||
 !Number.isInteger(d.buffer_count)||d.buffer_count<0||d.buffer_count>29||!Number.isInteger(d.dropped)||d.dropped<0||
 typeof d.auto!=='boolean'||typeof d.valve_open!=='boolean'||typeof d.sensor_valid!=='boolean'||typeof d.replay!=='boolean'||
 (d.sensor_valid?(!finite('temp_c')||!finite('air_humidity_pct')||d.air_humidity_pct<0||d.air_humidity_pct>100):(d.temp_c!==null||d.air_humidity_pct!==null)))return null;
const session=d.device+':'+d.boot_id;
let hist=context.get('hist')||[],sessions=context.get('sessions')||{};
let state=sessions[session];
const ack={payload:JSON.stringify({schema:2,device:d.device,boot_id:d.boot_id,seq:d.seq}),retain:false};
if(state&&d.seq<=state.last){const outputs=Array(13).fill(null);outputs[12]=ack;return outputs;}
if(!state)state={anchor:Date.now()-d.sent_uptime_ms,last:0,gaps:0,seen:Date.now()};
const missing=Math.max(0,d.seq-state.last-1);
state.gaps+=missing;state.last=d.seq;state.seen=Date.now();sessions[session]=state;
for(const key of Object.keys(sessions).sort((a,b)=>sessions[b].seen-sessions[a].seen).slice(16))delete sessions[key];
const ts=state.anchor+d.uptime_ms;
hist.push({session,seq:d.seq,x:ts,uptime_ms:d.uptime_ms,soil:d.soil_pct,t:d.temp_c,h:d.air_humidity_pct,
 sensor_valid:d.sensor_valid,valve_open:d.valve_open,auto:d.auto,setpoint:d.setpoint,replay:d.replay,dropped:d.dropped});
hist.sort((a,b)=>a.x-b.x||a.seq-b.seq);if(hist.length>500)hist=hist.slice(-500);
// Contexto salvo antes do ACK. RAM do Node-RED: persistência em disco não é prometida.
context.set('hist',hist);context.set('sessions',sessions);context.set('latest',d);
const series=(key,label)=>[{series:[label],data:[hist.flatMap((x,i)=>{
 const previous=hist[i-1],gap=previous&&previous.session===x.session&&x.seq>previous.seq+1;
 const point={x:x.x,y:x[key]};return gap?[{x:x.x-1,y:null},point]:[point];
})],labels:['']}];
// O histórico e o ACK acima permanecem iguais. Replay não substitui o estado ao vivo.
if(!d.replay)context.set('lastLive',d);
const lastLive=context.get('lastLive');
const status=d.replay
 ? (lastLive?'REENVIO · Última leitura ao vivo; comandos pausados':'REENVIO · Aguardando primeira leitura ao vivo')
 : `${d.auto?'AUTOMÁTICO':'MANUAL'} · Válvula ${d.valve_open?'ABERTA':'FECHADA'} · Alvo ${d.setpoint}%${d.sensor_valid?'':' · DHT22 SEM LEITURA'}`;
const hold=(key)=>lastLive?{payload:lastLive[key],enabled:false}:{enabled:false};
return [
 d.replay?null:{payload:d.soil_pct},d.replay?null:{payload:d.temp_c},d.replay?null:{payload:d.air_humidity_pct},
 {payload:status,replay:d.replay},{payload:{count:d.buffer_count,dropped:d.dropped,seq:d.seq,replay:d.replay,gaps:state.gaps}},
 {payload:series('soil','Umidade do solo (%)')},{payload:series('t','Temperatura (°C)')},{payload:series('h','Umidade do ar (%)')},
 {payload:d.replay?'ESTADO NÃO CONFIRMADO':(d.valve_open?'ABERTA':'FECHADA')},
 d.replay?hold('auto'):{payload:d.auto,enabled:true},
 d.replay?hold('valve_open'):{payload:d.valve_open,enabled:!d.auto},
 d.replay?hold('setpoint'):{payload:d.setpoint,enabled:true},ack
];
